 useEffect(()=>{if(navigationPending.current&&!navOpen){navigationPending.current=false;mainRef.current?.focus({preventScroll:true});}},[view,navOpen]);
 useEffect(()=>{if(!signedIn||demo){setBankCandidates({});return;}let active=true;const abort=new AbortController();fetch('/api/bank/invoice-candidates',{cache:'no-store',signal:abort.signal}).then(async r=>{if(!r.ok)return;const out:any=await r.json();if(active)setBankCandidates(out.candidates||{});}).catch(()=>{});return()=>{active=false;abort.abort();};},[signedIn,demo,revision]);
 const operation=useRef(false),loadVersion=useRef(0),real=useRef<{state:State;revision:number;audit:any[]}|null>(null);
 const load=useCallback(async(silent=false)=>{const version=++loadVersion.current;if(!silent)setLoading(true);try{const res=await fetch('/api/state',{cache:'no-store'}),data:any=await res.json();if(version!==loadVersion.current)return;if(!res.ok){if(res.status===401){setSignedIn(false);setState(emptyState());setAudit([]);setModal(null);setError('');return;}throw new Error(data.error??'Kunde inte hämta dina uppgifter.');}setState(data.state);setRevision(data.revision);setAudit(data.audit??[]);setSignedIn(true);setError('');setLoadedAt(new Date().toLocaleTimeString('sv-SE',{hour:'2-digit',minute:'2-digit'}));}catch(e){setError(messageOf(e));}finally{if(!silent)setLoading(false);}},[]);
 useEffect(()=>{void load();},[load]);useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),6000);return()=>clearTimeout(t);},[toast]);
