 function openTask(task:ControlTask){if(task.type==='document'){setDocumentId(task.entity_id);navigate('documents');}else if(task.type==='message'){setMessageId(task.entity_id);navigate('messages');}else if(task.transaction_id||['payment','specification'].includes(task.type))setModal({kind:'tx',id:task.transaction_id||task.entity_id});else if(task.invoice_id||['invoice','anomaly'].includes(task.type))setModal({kind:'detail',id:task.invoice_id||task.entity_id});}
 function openMessage(id:string){setMessageId(id);setModal(null);navigate('messages');}
 function navigate(v:View){if(v===view&&!navOpen)mainRef.current?.focus({preventScroll:true});else navigationPending.current=true;setView(v);setFilter('all');setSearch('');setNavOpen(false);if(signedIn&&!demo){void load(true);void control.refresh();}}
 const save:Save=async command=>{if(operation.current)return false;if(!signedIn&&!demo){setError('Logga in med ChatGPT för att spara dina uppgifter. Du kan också prova demoläget.');return false;}operation.current=true;setBusy(true);setError('');try{
  if(demo){const result=applyCommand(state,command);setState(result.state);setAudit(a=>[{id:uid(),action:command.type,detail:JSON.stringify({message:result.message,command}),created_at:new Date().toISOString()},...a]);setToast(result.message+' · endast i demo');}
  else{const res=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,requestId:uid(),command})}),data:any=await res.json();if(!res.ok)throw new Error(data.error??'Ändringen kunde inte sparas.');setState(data.state);setRevision(data.revision);setAudit(a=>[{id:uid(),action:command.type,detail:JSON.stringify({message:data.message,command}),created_at:new Date().toISOString()},...a]);setToast(data.message);setLoadedAt(new Date().toLocaleTimeString('sv-SE',{hour:'2-digit',minute:'2-digit'}));}return true;
 }catch(e){setError(messageOf(e));return false;}finally{setBusy(false);operation.current=false;}};
 function toggleDemo(){if(operation.current)return;loadVersion.current++;setLoading(false);setModal(null);setError('');setFilter('all');if(demo){if(real.current){setState(real.current.state);setRevision(real.current.revision);setAudit(real.current.audit);}setDemo(false);if(signedIn)void load();}else{real.current={state,revision,audit};setState(demoState());setAudit([]);setDemo(true);}setView('overview');}
 const active=state.invoices.filter(i=>!i.voided&&i.reviewed),receivables=active.filter(i=>i.direction==='receivable'),payables=active.filter(i=>i.direction==='payable');
 const remaining=(list:Invoice[])=>list.reduce((n,i)=>n+Math.max(balance(state,i),0),0);
 const outstanding=remaining(receivables),toPay=remaining(payables),overdue=active.filter(i=>balance(state,i)>0&&i.due&&i.due<today()),unmatched=state.transactions.filter(t=>!t.ignored&&t.kind!=='batch'&&available(state,t)>0),needsReview=state.invoices.filter(i=>!i.reviewed&&!i.voided),matches=state.transactions.flatMap(t=>suggestions(state,t).filter(m=>m.amount>0).map(m=>({...m,transaction:t}))),strongMatches=matches.filter(m=>m.strength==='strong');
