 async function exportData(){try{let data:any;if(demo)data={state,audit,format:'MG-Fakturakoll-1',demo:true};else{const res=await fetch('/api/export');data=await res.json();if(!res.ok)throw new Error(data.error);}downloadFile(`mg-fakturakoll-${today()}${demo?'-demo':''}.json`,JSON.stringify(data,null,2),'application/json');setToast('Dataexport nedladdad. Bilagor laddas ned separat från fakturorna.');}catch(e){setError(messageOf(e));}}
 function exportInvoices(){const rows=[['Fakturatyp','Kund/leverantör','Fakturanummer','Fakturadatum','Förfallodatum','Belopp SEK','Krediterat SEK','Betalt SEK','Kvar SEK','Status','OCR']];for(const i of filteredInvoices)rows.push([i.direction==='receivable'?'Kundfaktura':'Leverantörsfaktura',i.party,i.number,i.issued,i.due,inputMoney(i.total),inputMoney(credited(state,i.id)),inputMoney(paid(state,i.id)),inputMoney(balance(state,i)),invoiceStatus(state,i).label,i.ocr]);downloadFile(`fakturor-${today()}.csv`,'\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}


